import {createStudy,canvasSurface,seededRandom,clamp,downloadCanvas} from './core.js';
const study=createStudy({id:12,title:'Spring Choir',category:'Physics / Resonance',accent:'#ff62bb',background:'#111017',foreground:'#f4e7ed'});
const canvas=document.querySelector('#choir-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
const cols=18,rows=19,palette=['#ff62bb','#ff7b87','#ffa26b','#df96ff','#a69aff'];let nodes=[],links=[],pointer={x:-1000,y:-1000,active:false},tension=24,damping=7;
function reset(restoreControls=false){if(restoreControls){tension=24;damping=7;document.querySelector('#choir-tension').value=24;document.querySelector('#choir-damping').value=7;document.querySelector('#tension-value').textContent=24;document.querySelector('#damping-value').textContent=7}pointer={x:-1000,y:-1000,active:false};document.querySelector('#choir-x').textContent='—';document.querySelector('#choir-y').textContent='—';nodes=[];links=[];const{width:w,height:h}=surface;const left=w*.32,span=w*.53,top=h*.08,vertical=h*.72;for(let c=0;c<cols;c++)for(let r=0;r<rows;r++){const f=r/(rows-1),x=left+c/(cols-1)*span+Math.sin(f*Math.PI)*Math.sin(c*.35)*span*.11,y=top+f*vertical;nodes.push({x,y,bx:x,by:y,vx:Math.sin(r*.31+c)*12,vy:0,pinned:r===0||r===rows-1,c,r})}for(let c=0;c<cols;c++)for(let r=0;r<rows;r++){const i=c*rows+r;if(r<rows-1)add(i,i+1);if(c<cols-1&&r%3===0)add(i,i+rows)}draw(0);}
function add(a,b){links.push({a,b,rest:Math.hypot(nodes[a].x-nodes[b].x,nodes[a].y-nodes[b].y)})}
function draw(time){const{ctx,width:w,height:h}=surface;if(!ctx)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#111017';ctx.fillRect(0,0,w,h);for(let c=0;c<cols;c++){const color=palette[Math.floor(c/cols*palette.length)];ctx.beginPath();for(let r=0;r<rows;r++){const n=nodes[c*rows+r];r?ctx.lineTo(n.x,n.y):ctx.moveTo(n.x,n.y)}ctx.strokeStyle=color;ctx.lineWidth=c%3===0?1.8:1;ctx.globalAlpha=.85;ctx.stroke()}ctx.globalAlpha=.18;ctx.lineWidth=.6;for(let r=3;r<rows-1;r+=3){ctx.beginPath();for(let c=0;c<cols;c++){const n=nodes[c*rows+r];c?ctx.lineTo(n.x,n.y):ctx.moveTo(n.x,n.y)}ctx.strokeStyle='#f5c8df';ctx.stroke()}ctx.globalAlpha=1;for(let c=0;c<cols;c++){const n=nodes[c*rows];ctx.beginPath();ctx.arc(n.x,n.y,2.4,0,Math.PI*2);ctx.fillStyle=palette[Math.floor(c/cols*palette.length)];ctx.fill()}if(pointer.active){ctx.beginPath();ctx.arc(pointer.x,pointer.y,20+Math.sin(time*2)*2,0,Math.PI*2);ctx.strokeStyle='#f5c8df66';ctx.lineWidth=.7;ctx.stroke();ctx.beginPath();ctx.arc(pointer.x,pointer.y,2,0,Math.PI*2);ctx.fillStyle='#fff0f7';ctx.fill()}}
function frame({dt,time}){if(dt>0){for(let sub=0;sub<3;sub++){const t=dt/3;for(const n of nodes){n.fx=(n.bx-n.x)*tension*.35-n.vx*damping;n.fy=(n.by-n.y)*tension*.35-n.vy*damping;if(!n.pinned){n.fx+=Math.sin(time*.9+n.r*.24+n.c*.3)*10;if(pointer.active){const dx=n.x-pointer.x,dy=n.y-pointer.y,d=Math.hypot(dx,dy);if(d<150&&d>.01){const f=(1-d/150)*800;n.fx+=dx/d*f;n.fy+=dy/d*f}}}}for(const link of links){const a=nodes[link.a],b=nodes[link.b],dx=b.x-a.x,dy=b.y-a.y,length=Math.hypot(dx,dy)||.001,force=(length-link.rest)*tension*.65,fx=dx/length*force,fy=dy/length*force;a.fx+=fx;a.fy+=fy;b.fx-=fx;b.fy-=fy}for(const n of nodes){if(n.pinned){n.x=n.bx;n.y=n.by;continue}n.vx=clamp(n.vx+n.fx*t,-750,750);n.vy=clamp(n.vy+n.fy*t,-750,750);n.x+=n.vx*t;n.y+=n.vy*t;}}}draw(time)}
canvas.addEventListener('pointermove',event=>{const r=canvas.getBoundingClientRect();pointer={x:event.clientX-r.left,y:event.clientY-r.top,active:true};document.querySelector('#choir-x').textContent=Math.round(pointer.x);document.querySelector('#choir-y').textContent=Math.round(pointer.y);study.invalidate()});canvas.addEventListener('pointerleave',()=>{pointer.active=false;study.invalidate()});
document.querySelector('#choir-tension').addEventListener('input',event=>{tension=+event.target.value;document.querySelector('#tension-value').textContent=tension;study.invalidate()});document.querySelector('#choir-damping').addEventListener('input',event=>{damping=+event.target.value;document.querySelector('#damping-value').textContent=damping;study.invalidate()});
document.querySelector('#choir-pluck').addEventListener('click',()=>{const rand=seededRandom(1221);for(const n of nodes)if(!n.pinned){n.x+=Math.sin(n.r/(rows-1)*Math.PI)*48;n.vx+=(rand()-.25)*190;n.vy+=(rand()-.5)*80}study.invalidate()});
study.setReset(()=>reset(true));study.setExport(()=>downloadCanvas(canvas,'12-spring-choir.png'));study.onResize(reset);study.onFrame(frame);study.cleanup(()=>surface.dispose());reset();
